  values (v_part_1, 'Conjunction — বাক্য জোড়া লাগানো', 'lesson-13', 'Lesson 13 from English Foundation.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"and, but, because, so, if, although"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 এই Lesson শেষে তুমি যা পারবে"}]},{"type":"paragraph","content":[{"type":"text","text":"১. ছোট ছোট বাক্য জুড়ে বড় ও সুন্দর বাক্য বানাতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. ১২টি দরকারি conjunction উচ্চারণসহ শিখবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. because ও so-এর পার্থক্য বুঝবে (কারণ বনাম ফলাফল)।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. বাংলা থেকে আসা দুইটি বড় ভুল ঠিক করবে (Although…but…, Because…so…)।"}]},{"type":"paragraph","content":[{"type":"text","text":"৫. if দিয়ে শর্তযুক্ত বাক্য বানাতে পারবে (If it rains, I will not go.)।"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🔄 শুরুর আগে — Lesson 12 ঝালাই করো"}]},{"type":"paragraph","content":[{"type":"text","text":"১. ভুল ঠিক করো: What you are doing?"}]},{"type":"paragraph","content":[{"type":"text","text":"২. ____ old are you?"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. Tag বসাও: He is busy, ____?"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. ভুল ঠিক করো: Who did call you? উত্তর:"}]},{"type":"paragraph","content":[{"type":"text","text":"1. What are you doing?"}]},{"type":"paragraph","content":[{"type":"text","text":"2. How"}]},{"type":"paragraph","content":[{"type":"text","text":"3. isn''t he"}]},{"type":"paragraph","content":[{"type":"text","text":"4. Who called you?"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ১ — Conjunction কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"যে শব্দ দুইটি শব্দ, বাক্যাংশ বা বাক্যকে জোড়া লাগায়, তাকে Conjunction (সংযোজক অব্যয়) বলে। এতদিন তুমি ছোট ছোট বাক্য বানাচ্ছিলে — এবার সেগুলো জুড়ে বড় বাক্য বানাবে।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ছোট বাক্য"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"জোড়া লাগানোর পর"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I am poor. I am honest."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I am poor but honest."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He was ill. He did not come."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He did not come because he was ill."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"It rained. We stayed at home."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"It rained, so we stayed at home."}}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১.১ ১২টি দরকারি Conjunction — উচ্চারণসহ"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"English Word"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলা উচ্চারণ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"IPA"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলা অর্থ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"and"}}]}]},{"