agraph","content":[{"type":"pronounce","attrs":{"text":"It was done by him."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Past Continuous"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He was doing it."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"was / were being + V3"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"It was being done by him."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Past Perfect"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He had done it."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"had been + V3"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"It had been done by him."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Future Indefinite"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He will do it."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"will be + V3"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"It will be done by him."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Future Perfect"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He will have done it."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"will have