  -- Lesson 16: Narration — Direct ও Indirect Speech

  values (v_part_1, 'Narration — Direct ও Indirect Speech', 'lesson-16', 'Lesson 16 from English Foundation.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"কেউ যা বলল, তা অন্যকে বলা"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 এই Lesson শেষে তুমি যা পারবে"}]},{"type":"paragraph","content":[{"type":"text","text":"১. কারো কথা হুবহু না বলে নিজের ভাষায় বলতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. Narration-এর ৫টি মূল নিয়ম শিখবে (Reporting verb, Pronoun, Tense, সময়-শব্দ, যতিচিহ্ন)।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. চার ধরনের বাক্য (বর্ণনামূলক, প্রশ্ন, আদেশ, বিস্ময়) — সবগুলোর নিয়ম জানবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. কোন ক্ষেত্রে Tense বদলায় না, তা বুঝবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৫. পরীক্ষায় Narration-এর যেকোনো প্রশ্ন করতে পারবে।"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🔄 শুরুর আগে — Lesson 15 ঝালাই করো"}]},{"type":"paragraph","content":[{"type":"text","text":"১. Passive করো: He does the work."}]},{"type":"paragraph","content":[{"type":"text","text":"২. ভুল ঠিক করো: It is done by he."}]},{"type":"paragraph","content":[{"type":"text","text":"৩. Passive-এ verb-এর কোন রূপ বসে? উত্তর:"}]},{"type":"paragraph","content":[{"type":"text","text":"1. The work is done by him."}]},{"type":"paragraph","content":[{"type":"text","text":"2. It is done by him."}]},{"type":"paragraph","content":[{"type":"text","text":"3. V3 (Past Participle)"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ১ — Narration কী?"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ধরন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কী"}]}]}