nt":[{"type":"pronounce","attrs":{"text":"said to"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"told"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"He said to me → He told me that…"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"said to (প্রশ্নে)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"asked"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"He said to me, \"Where…\" → He asked me where…"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"said to (আদেশে)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"told / ordered / requested / advised"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He told me to go."}}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১.২ পাঁচটি মূল নিয়ম"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"নিয়ম"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কী করবে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১. যতিচিহ্ন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কমা ও উদ্ধৃতি চিহ্ন (\" \") তুলে দাও, বদলে \"that\" বসাও।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"২. Pronoun"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বক্তা অনুযায়ী pronoun বদলাও (নিচের SON নিয়ম দেখো)।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৩. Tense"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Reporting verb past হলে ভেতরের Tense এক ধাপ পেছাও।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৪. সময় ও স্থান"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"now → then, today → that day, here → there ইত্যাদি।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৫. বাক্যের ধরন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রশ্ন, আদেশ, বিস্ময় — প্রত্যেকের আলাদা নিয়ম।"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ২ — Pronoun বদলানোর নিয়ম (SON)"}]},{"type":"paragraph","content":[{"type":"text","text":"S = Subject অনুযায়ী,  O = Object অনুযায়ী,  N = No change"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Pronoun"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কী হবে"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১ম পুরুষ (I, we, my, our)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Reporting verb-এর Subject অনুযায়ী"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"He said, \"I am ill.\" → He said that he was ill."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"২য় পুরুষ (you, your)"}]}]},{"type":"tableCell","