type":"paragraph","content":[{"type":"text","text":"\"I am going\" → he was going"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Present Perfect (have gone)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Past Perfect (had gone)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"I have gone\" → he had gone"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Past Indefinite (went)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Past Perfect (had gone)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"I went\" → he had gone"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Past Continuous (was going)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Past Perfect Continuous"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"I was going\" → he had been going"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"will"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"would"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"I will go\" → he would go"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"can"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"could"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"I can go\" → he could go"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"may"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"might"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"I may go\" → he might go"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"must"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"had to / must"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"I must go\" → he had to go"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"⚠️ যেখানে Tense বদলাবে না"}]},{"type":"paragraph","content":[{"type":"text","text":"১. চিরন্তন সত্য: He said, \"The sun rises in the east.\" → He said that the sun rises in the east."}]},{"type":"paragraph","content":[{"type":"text","text":"২. অভ্যাসগত সত্য: He said, \"I take tea every morning.\" → …that he takes tea every morning."}]},{"type":"paragraph","content":[{"type":"text","text":"৩. ইতিহাসের ঘটনা: He said, \"Bangladesh became independent in 1971.\""}]},{"type":"paragraph","content":[{"type":"text","text":"৪. Reporting verb present/future হলে: He says, \"I am ill.\" → He says that he is ill."}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৩.১ সময় ও স্থানের শব্দ"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Direct"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Indirect"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Direct"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"ty