tent":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"last night"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"the previous night"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"next week"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"the following week"}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"thus"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"so"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"come"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"go"}}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৪ — চার ধরনের বাক্য"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.১ বর্ণনামূলক (Assertive) — that বসে"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"He said, \"I am ill.\" → He said that he was ill.  →  সে বলল যে সে অসুস্থ।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"She said, \"I will come.\" → She said that she would come.  →  সে বলল যে সে আসবে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"He said to me, \"You are right.\" → He told me that I was right.  →  সে আমাকে বলল যে আমি ঠিক।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"They said, \"We have finished.\" → They said that they had finished.  →  তারা বলল যে তারা শেষ করেছে।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.২ প্রশ্নবোধক (Interrogative)"}]},{"type":"paragraph","content":[{"type":"text","text":"Yes/No প্রশ্ন → asked … if / whether        Wh-প্রশ্ন → asked … + Wh-word"}]},{"type":"paragraph","content":[{"type":"text","text":"গুরুত্বপূর্ণ: Indirect-এ প্রশ্নের গঠন আর প্রশ্ন থাকে না — সাধারণ বাক্যের মতো হয়ে যায়, প্রশ্নবোধক চিহ্নও উঠে যায়।"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"He said to me, \"Are you ill?\" → He asked me if I was ill.  →  সে আমাকে জিজ্ঞেস করল আমি অসুস্থ কিনা।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"He said to me, \"Where do you live?\" → He asked me where I lived.  →  সে জিজ্ঞেস করল আমি কোথায় থাকি।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"She said to him, \"What is your name?\" → She asked him what his name was.  →  সে জিজ্ঞেস করল তার নাম কী।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"He said, \"Did you go there?\" → He asked if I had gone there.  →  সে জিজ্ঞেস করল আমি সেখানে গিয়েছিলাম কিনা।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🚨 এখানেই সবচেয়ে বেশি ভুল হয় ❌ He asked me where do I live."}]},{"type":"paragraph","content":[{"type":"text","text":"✅ He asked me where I lived. নিয়ম: Indirect-এ do / does / did উঠে যায় এবং শব্দক্রম সাধারণ বাক্যের মতো হয় (subject আগে, verb পরে)।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.৩ আদেশ / অনুরোধ (Imperative)"}]},{"type":"paragraph","content":[{"type":"text","text":"told / ordered / requested / advised  +  object  +  to  +  verb"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ধরন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Reporting verb"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আদেশ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ordered / told"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"He said to me, \"Go there.\" → He told me to go there."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অনুরোধ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"requested"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"He said, \"Please help me.\" → He requested me to help him."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"উপদেশ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"advised"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"He said, \"Study hard.\" → He advised me to study hard."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নিষেধ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"forbade / told not to"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"He said, \"Do not go.\" → He told me not to go."}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"📌 না-বাচক আদেশে \"not to\" বসে — He told me not to go there."}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.৪ বিস্ময়সূচক (Exclamatory)"}]},{"type":"paragraph","content":[{"type":"text","text":"exclaimed with joy / sorrow / wonder  +  that"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"He said, \"How beautiful the flower is!\" → He exclaimed with wonder that the flower was very beautiful.  →  সে বিস্ময়ের সাথে বলল ফুলটি খুব সুন্দর।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"She said, \"Alas! I am undone.\" → She exclaimed with sorrow that she was undone.  →  সে দুঃখের সাথে বলল যে সে সর্বনাশ হয়েছে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"They said, \"Hurrah! We have won.\" → They exclaimed with joy that they had won.  →  তারা আনন্দের সাথে বলল যে তারা জিতেছে।"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৫ — ৮টি Common Mistake"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"❌ ভুল"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ শুদ্ধ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কারণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He said that he is ill."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He said that he was ill."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"said past → ভেতরের tense পেছাবে।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He asked me where do I live."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He asked me where I lived."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Indirect-এ do উঠে যায়।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He asked that I was ill."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He asked if I was ill."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes/No প্রশ্নে if / whether।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"He said to me that…"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"He told me that…"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"said to → told।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He told me to not go."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He told me not to go."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"not\" আগে, \"to\" পরে।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"He said me that…"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"He told me that… / He said that…"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"said-এর পরে সরাসরি object বসে না।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He said that the sun rose in the east."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He said that the sun rises in the east."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"চিরন্তন সত্য বদলায় না।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"He asked me where I lived?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He asked me where I lived."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Indirect-এ প্রশ্নবোধক চিহ্ন থাকে না।"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৮ — আজকের হোমওয়ার্ক"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"✍️ ৪৫ মিনিটের কাজ"}]},{"type":"paragraph","content":[{"type":"text","text":"১. অংশ ৩-এর Tense-বদলের ছকটা খাতায় লেখো — অন্তত ২ বার।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. আজ কেউ তোমাকে যা যা বলেছে, তার ৫টি Indirect Speech-এ লেখো: My mother told me that…"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. চার ধরনের বাক্যের ৩টি করে উদাহরণ লেখো — মোট ১২টি।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. সময়ের শব্দের ছকটা (now → then) মুখস্থ করো — পরীক্ষায় এখানেই নম্বর কাটা যায়।"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"✅ তুমি বুঝবে কীভাবে যে Lesson 16 শেষ? যদি \"He asked me where I lived\" লিখতে গিয়ে তোমার হাত আপনাআপনি do বাদ দেয়, এবং প্রশ্নবোধক চিহ্ন না বসায় — তাহলে Lesson 16 তোমার হয়ে গেছে। এই দুটোই পরীক্ষায় সবচেয়ে বেশি নম্বর কাটার কারণ।"}]}]}]}'::jsonb, 'published', 'intermediate', 47, now())
  returning id into v_lesson;

