  -- Lesson 17: Conditional Sentence — If-এর তিন প্রকার

  values (v_part_1, 'Conditional Sentence — If-এর তিন প্রকার', 'lesson-17', 'Lesson 17 from English Foundation.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"বাস্তব শর্ত, অবাস্তব কল্পনা ও অতীতের আফসোস"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 এই Lesson শেষে তুমি যা পারবে"}]},{"type":"paragraph","content":[{"type":"text","text":"১. If দিয়ে তিন ধরনের শর্তযুক্ত বাক্য বানাতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. বাস্তব শর্ত ও কল্পনার পার্থক্য বুঝবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. \"If I were you…\" কেন was নয় were — তা জানবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. অতীতের আফসোস প্রকাশ করতে পারবে (If I had studied, I would have passed.)।"}]},{"type":"paragraph","content":[{"type":"text","text":"৫. একই বাক্যে দুইবার will/would বসানোর ভুল চিরতরে বন্ধ করবে।"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🔄 শুরুর আগে — Lesson 16 ঝালাই করো"}]},{"type":"paragraph","content":[{"type":"text","text":"১. Indirect করো: He said, \"I am ill.\""}]},{"type":"paragraph","content":[{"type":"text","text":"২. ভুল ঠিক করো: He asked me where do I live. উত্তর:"}]},{"type":"paragraph","content":[{"type":"text","text":"1. He said that he was ill."}]},{"type":"paragraph","content":[{"type":"text","text":"2. He asked me where I lived."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ১ — Conditional Sentence কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"\"যদি … তাহলে …\" — এমন বাক্য। দুইটি অংশ থাকে: শর্ত (If-clause) এবং ফলাফল (Main clause)।"}]},{"type":"paragraph","content":[{"type":"text","text":"If  +  শর্ত  ,  ফলাফল          বা          ফলাফল  +  if  +  শর্ত"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"📌 If সামনে থাকলে মাঝখানে কমা বসে। পরে থাকলে কমা লাগে না।"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If it rains, I will not go.   =   I will not go if it rains."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১.১ চার প্রকার — এক নজরে"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রকার"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কী বোঝায়"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"গঠন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Type 0"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"চিরন্তন সত্য"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"If + Present, Present"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"If you heat water, it boils."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Type 1"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বাস্তব ভবিষ্যৎ শর্ত"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"If + Present, will + verb"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"If it rains, I will stay home."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Type 2"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বর্তমানের কল্পনা (অবাস্তব)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"If + Past, would + verb"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"If I were rich, I would help you."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Type 3"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অতীতের আফসোস"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"If + had + V3, would have + V3"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"If I had studied, I would have passed."}}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ২ — Type 0 ও Type 1 (বাস্তব)"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২.১ Type 0 — চিরন্তন সত্য"}]},{"type":"paragraph","content":[{"type":"text","text":"If  +  Present Tense ,  Present Tense"}]},{"type":"paragraph","content":[{"type":"text","text":"যা সবসময় ঘটে — বিজ্ঞান, প্রকৃতি, নিয়ম। এখানে \"if\"-এর বদলে \"when\"ও বসানো যায়।"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If you heat water, it boils.  →  পানি গরম করলে তা ফোটে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If you drop a stone, it falls.  →  পাথর ছেড়ে দিলে তা পড়ে যায়।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If you do not eat, you feel hungry.  →  না খেলে ক্ষুধা লাগে।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২.২ Type 1 — বাস্তব ভবিষ্যৎ শর্ত"}]},{"type":"paragraph","content":[{"type":"text","text":"If  +  Present Tense ,  will / can / may  +  Verb"}]},{"type":"paragraph","content":[{"type":"text","text":"ভবিষ্যতে সত্যিই ঘটতে পারে — এমন শর্ত। এটাই সবচেয়ে বেশি ব্যবহৃত।"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If it rains, I will not go out.  →  যদি বৃষ্টি হয়, আমি বাইরে যাব না।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If you study hard, you will pass.  →  যদি কঠোর পরিশ্রম করো, তুমি পাস করবে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If he comes, I will tell him.  →  যদি সে আসে, আমি তাকে বলব।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If you help me, I can finish it today.  →  যদি তুমি সাহায্য করো, আমি আজই শেষ করতে পারব।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If you are late, you will miss the bus.  →  দেরি করলে তুমি বাস মিস করবে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If I get time, I will call you.  →  সময় পেলে আমি তোমাকে ফোন করব।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🚨 ১ নম্বর ভুল ❌ If it will rain, I will not go."}]},{"type":"paragraph","content":[{"type":"text","text":"✅ If it rains, I will not go. নিয়ম: If-এর অংশে কখনো will বসে না — যদিও অর্থ ভবিষ্যৎ। একই বাক্যে একবারই will।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৩ — Type 2 (বর্তমানের কল্পনা)"}]},{"type":"paragraph","content":[{"type":"text","text":"If  +  Past Tense ,  would / could / might  +  Verb (মূল রূপ)"}]},{"type":"paragraph","content":[{"type":"text","text":"যা এখন সত্যি নয়, শুধু কল্পনা। বাংলায় — \"যদি আমি ধনী হতাম, তাহলে…\""}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If I were rich, I would help the poor.  →  যদি আমি ধনী হতাম, গরিবদের সাহায্য করতাম।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If I were you, I would not do that.  →  আমি যদি তোমার জায়গায় হতাম, ওটা করতাম না।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If I had a car, I would go there.  →  যদি আমার গাড়ি থাকত, আমি সেখানে যেতাম।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If he studied hard, he would pass.  →  সে যদি কঠোর পরিশ্রম করত, পাস করত।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If I knew his address, I would write to him.  →  তার ঠিকানা জানলে আমি তাকে চিঠি লিখতাম।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If I could fly, I would visit the moon.  →  উড়তে পারলে আমি চাঁদে যেতাম।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🔑 was নয়, were — এটাই নিয়ম Type 2-এ সব subject-এর সাথেই were বসে — I, he, she, it সবার জন্য।"}]},{"type":"paragraph","content":[{"type":"text","text":"✅ If I were you…"}]},{"type":"paragraph","content":[{"type":"text","text":"✅ If he were here… ❌ If I was you…  (কথ্য ভাষায় অনেকে বলে, কিন্তু লেখায় ও পরীক্ষায় ভুল) কারণ: এটা বাস্তব অতীত নয়, কল্পনা — তাই আলাদা রূপ ব্যবহার হয়।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৪ — Type 3 (অতীতের আফসোস)"}]},{"type":"paragraph","content":[{"type":"text","text":"If  +  had  +  V3 ,  would have / could have  +  V3"}]},{"type":"paragraph","content":[{"type":"text","text":"অতীতে যা হয়নি, তা নিয়ে আফসোস। বাংলায় — \"যদি পড়তাম, তাহলে পাস করতাম\" (কিন্তু পড়িনি, ফেল করেছি)।"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If I had studied hard, I would have passed.  →  যদি কঠোর পরিশ্রম করতাম, পাস করতাম।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If he had come earlier, he would have met me.  →  সে আগে এলে আমার সাথে দেখা হতো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If I had known, I would have helped you.  →  জানলে আমি তোমাকে সাহায্য করতাম।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If she had taken the medicine, she would have recovered.  →  ওষুধ খেলে সে সুস্থ হয়ে যেত।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If we had left early, we would not have missed the train.  →  আগে বের হলে আমরা ট্রেন মিস করতাম না।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🧠 তিন প্রকারের পার্থক্য এক উদাহরণে Type 1: If I study hard, I will pass.  — এখনো সময় আছে, হতে পারে। Type 2: If I studied hard, I would pass.  — এখন পড়ছি না, তাই হচ্ছে না। Type 3: If I had studied hard, I would have passed.  — পড়িনি, ফেল করেছি। এখন আর কিছু করার নেই।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৫ — unless ও অন্যান্য"}]},{"type":"paragraph","content":[{"type":"text","text":"unless = if … not (যদি না)। তাই unless-এর পরে আর \"not\" বসে না।"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Unless you study, you will fail.  →  পড়াশোনা না করলে তুমি ফেল করবে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"I will not go unless he calls me.  →  সে না ডাকলে আমি যাব না।"}]}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"শব্দ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"অর্থ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"unless"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"যদি না"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Unless you hurry, you will be late."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"as if / as though"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"যেন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He talks as if he knew everything."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"provided that"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শর্তসাপেক্ষে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"You can go provided that you finish the work."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"in case"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"যদি হয় সেই ভয়ে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Take an umbrella in case it rains."}}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"📌 as if-এর পরেও Type 2-এর মতো were বসে — He behaves as if he were a king."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৬ — ৮টি Common Mistake"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"❌ ভুল"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ শুদ্ধ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":