","content":[{"type":"text","text":"শিওর"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নিশ্চয়ই"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Please."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্লীজ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"দয়া করে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Just a moment."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"জাস্ট অ্যা মৌমেন্ট"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একটু অপেক্ষা করুন"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Congratulations!"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কনগ্র্যাচুলেইশনস"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অভিনন্দন!"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Good luck!"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"গুড লাক"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শুভকামনা!"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"💡 \"Excuse me\" বনাম \"Sorry\" Excuse me — কিছু করার আগে। (কাউকে ডাকতে, পাশ কাটাতে, প্রশ্ন করতে) Sorry — ভুল করার পরে। (ধাক্কা লাগলে, দেরি করলে)"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৪ — না বুঝলে কী বলবে (সবচেয়ে জরুরি অংশ)"}]},{"type":"paragraph","content":[{"type":"text","text":"নতুন শিক্ষার্থী