ype":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"What does ______ mean?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"হোয়াট ডাজ ____ মীন?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"____ মানে কী?"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you say ______ in English?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"হাউ ডু ইউ সেই ____ ইন ইংলিশ?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"____ ইংরেজিতে কী বলে?"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you spell it?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"হাউ ডু ইউ স্পেল ইট?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"এটার বানান কী?"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Is that right?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ইজ দ্যাট রাইট?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"এটা কি ঠিক হলো?"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Sorry, my English is not good."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সরি, মাই ইংলিশ ইজ নট গুড"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"দুঃখিত, আমার ইংরেজি ভালো নয়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Please correct me if I am wrong."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্লীজ কারেক্ট মী"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ভুল হলে শুধরে দেবেন"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🔑 এই একটা বাক্য তোমার ইংরেজি বদলে দেবে How do you say ______ in English? যে শব্দটা জানো না, সেটা বাংলায় বলে এই প্রশ্ন করো। প্রতিদিন ৫টা নতুন শব্দ এভাবে শিখলে বছরে ১৮০০ শব্দ।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৫ — ছয়টি বাস্তব পরিস্থিতি"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.১ দোকানে (At a shop)"}]},{"type":"paragraph","content":[{"type":"text","text":"You: Excuse me, how much is this?  —  শুনুন, এটার দাম কত?"}]},{"type":"paragraph","content":[{"type":"text","text":"Seller: It is 250 taka.  —  এটা ২৫০ টাকা।"}]},{"type":"paragraph","content":[{"type":"text","text":"You: That''s too expensive. Can you reduce the price?  —  এটা খুব দামি। দাম কমাতে পারবেন?"}]},{"type":"paragraph","content":[{"type":"text","text":"Seller: I can give it for 220.  —  ২২০ টাকায় দিতে পারি।"}]},{"type":"paragraph","content":[{"type":"text","text":"You: OK, I will take it. Do you have a smaller size?  —  ঠিক আছে, নেব। ছোট সাইজ আছে?"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.২ রাস্তা জিজ্ঞেস করা (Asking directions)"}]},{"type":"paragraph","content":[{"type":"text","text":"You: Excuse me, where is the railway station?  —  শুনুন, রেলস্টেশন কোথায়?"}]},{"type":"paragraph","content":[{"type":"text","text":"Man: Go straight and turn left.  —  সোজা যান, তারপর বাঁয়ে ঘুরুন।"}]},{"type":"paragraph","content":[{"type":"text","text":"You: How far is it from here?  —  এখান থেকে কতদূর?"}]},{"type":"paragraph","content":[{"type":"text","text":"Man: About ten minutes on foot.  —  হেঁটে প্রায় দশ মিনিট।"}]},{"type":"paragraph","content":[{"type":"text","text":"You: Thank you very much.  —  অসংখ্য ধন্যবাদ।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.৩ ফোনে (On the phone)"}]},{"type":"paragraph","content":[{"type":"text","text":"You: Hello, may I speak to Rahim?  —  হ্যালো, রহিমের সাথে কথা বলতে পারি?"}]},{"type":"paragraph","content":[{"type":"text","text":"Other: Who is calling, please?  —  কে বলছেন?"}]},{"type":"paragraph","content":[{"type":"text","text":"You: This is Misbah.  —  আমি মিসবাহ বলছি।"}]},{"type":"paragraph","content":[{"type":"text","text":"Other: Hold on, please.  —  একটু ধরুন।"}]},{"type":"paragraph","content":[{"type":"text","text":"You: Sorry, I will call you back later.  —  দুঃখিত, আমি পরে ফোন করব।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.৪ ডাক্তারের কাছে (At the doctor)"}]},{"type":"paragraph","content":[{"type":"text","text":"Doctor: What is the problem?  —  সমস্যা কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"You: I have a headache and a fever.  —  আমার মাথাব্যথা ও জ্বর।"}]},{"type":"paragraph","content":[{"type":"text","text":"Doctor: How long have you been suffering?  —  কতদিন ধরে ভুগছেন?"}]},{"type":"paragraph","content":[{"type":"text","text":"You: For three days.  —  তিন দিন ধরে।"}]},{"type":"paragraph","content":[{"type":"text","text":"Doctor: Take this medicine twice a day.  —  এই ওষুধটা দিনে দুইবার খাবেন।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.৫ রেস্টুরেন্টে (At a restaurant)"}]},{"type":"paragraph","content":[{"type":"text","text":"Waiter: What would you like to have?  —  আপনি কী নেবেন?"}]},{"type":"paragraph","content":[{"type":"text","text":"You: I would like rice and chicken curry.  —  আমি ভাত ও মুরগির তরকারি নেব।"}]},{"type":"paragraph","content":[{"type":"text","text":"You: Can I have a glass of water, please?  —  এক গ্লাস পানি দেবেন?"}]},{"type":"paragraph","content":[{"type":"text","text":"You: The food is delicious.  —  খাবারটা খুব সুস্বাদু।"}]},{"type":"paragraph","content":[{"type":"text","text":"You: Can I have the bill, please?  —  বিলটা দেবেন?"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.৬ শ্রেণিকক্ষে (In the classroom)"}]},{"type":"paragraph","content":[{"type":"text","text":"You: May I come in, sir?  —  স্যার, ভেতরে আসতে পারি?"}]},{"type":"paragraph","content":[{"type":"text","text":"You: May I ask a question?  —  একটা প্রশ্ন করতে পারি?"}]},{"type":"paragraph","content":[{"type":"text","text":"You: I have a doubt about this.  —  এটা নিয়ে আমার একটা সংশয় আছে।"}]},{"type":"paragraph","content":[{"type":"text","text":"You: Could you explain it again, please?  —  আবার একটু বুঝিয়ে দেবেন?"}]},{"type":"paragraph","content":[{"type":"text","text":"You: May I go out, sir?  —  স্যার, বাইরে যেতে পারি?"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৬ — স্বাভাবিক শোনানোর ছোট শব্দ"}]},{"type":"paragraph","content":[{"type":"text","text":"মুখস্থ বাক্য বললে রোবটের মতো শোনায়। এই শব্দগুলো মাঝে বসালে কথা স্বাভাবিক শোনায় — এবং ভাবার সময়ও পাওয়া যায়।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"English"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলা উচ্চারণ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলা অর্থ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Well…"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ওয়েল"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আসলে… (ভাবার সময় নিতে)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Actually…"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অ্যাকচুয়ালি"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আসলে…"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"You know…"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ইউ নৌ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বুঝতেই পারছ…"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I mean…"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আই মীন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আমি বলতে চাইছি…"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Let me think."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"লেট মী থিংক"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একটু ভাবতে দাও"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"By the way…"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বাই দ্য ওয়েই"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"যাই হোক / প্রসঙ্গক্রমে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"In fact…"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ইন ফ্যাক্ট"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রকৃতপক্ষে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"To be honest…"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"টু বী অনেস্ট"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সত্যি বলতে…"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৭ — কথা বলার ভয় কাটানোর ৭টি কৌশল"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কৌশল"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কী করবে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১. বাংলায় ভেবে অনুবাদ কোরো না"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"এতে দেরি হয় ও গঠন ভুল হয়। ছোট বাক্যে সরাসরি ইংরেজিতে ভাবার অভ্যাস করো।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"২. ভুলকে ভয় পেয়ো না"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ভুল না করে কেউ শেখে না। যে ভুল করতে ভয় পায়, সে কখনো বলতে শেখে না।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৩. ছোট বাক্য বলো"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তিন-চার শব্দের বাক্যই যথেষ্ট। বড় বাক্য বানাতে গিয়ে থেমে যাওয়ার চেয়ে ছোট বাক্য বলা ভালো।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৪. প্রতিদিন ১৫ মিনিট জোরে পড়ো"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"যেকোনো ইংরেজি লেখা জোরে পড়ো। জিভ ও মুখের পেশি অভ্যস্ত হবে।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৫. নিজের সাথে কথা বলো"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আয়নার সামনে বা মনে মনে — \"I am eating. Now I am going out.\""}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৬. শোনো বেশি"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ইংরেজি খবর, ভিডিও, পডকাস্ট। কান তৈরি না হলে মুখ তৈরি হবে না।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৭. একজন সঙ্গী খুঁজে নাও"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"দিনে ১০ মিনিট বন্ধুর সাথে শুধু ইংরেজিতে কথা বলো — যত ভুলই হোক।"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🚨 সবচেয়ে বড় ভুল যা প্রায় সবাই করে অনেকে ভাবে — \"আগে পুরো grammar শিখি, তারপর কথা বলা শুরু করব।\" এই \"তারপর\" কোনোদিন আসে না। সত্য হলো: তুমি এখন যতটুকু জানো, তা দিয়েই কথা বলা শুরু করা যায়। Lesson 1-এর \"I am a student\" দিয়েই শুরু করো।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৯ — আজকের হোমওয়ার্ক"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"✍️ প্রতিদিনের কাজ (এই Lesson একদিনের নয়)"}]},{"type":"paragraph","content":[{"type":"text","text":"১. অংশ ১, ৩ ও ৪-এর সব বাক্য একটা আলাদা খাতায় লিখে পকেটে রাখো।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. প্রতিদিন সকালে ঘুম থেকে উঠে ১০টি বাক্য জোরে বলো।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. দিনে অন্তত একবার কারো সাথে ইংরেজিতে একটি বাক্য বলো — যত ছোটই হোক।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. নতুন শোনা প্রতিটি শব্দ খাতায় লিখে রাখো (শব্দ + উচ্চারণ + অর্থ + একটি বাক্য)।"}]},{"type":"paragraph","content":[{"type":"text","text":"৫. সাত দিনের চ্যালেঞ্জটা শেষ করো — তারপর আবার শুরু করো।"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"✅ তুমি বুঝবে কীভাবে যে Lesson 18 শেষ? যদি অপরিচিত কেউ হঠাৎ ইংরেজিতে \"How are you? What do you do?\" জিজ্ঞেস করলে তুমি ভয় না পেয়ে অন্তত ৩০ সেকেন্ড কথা চালিয়ে যেতে পারো — তাহলে Lesson 18 তোমার হয়ে গেছে। মনে রেখো: নিখুঁত ইংরেজি লক্ষ্য নয়। থেমে না গিয়ে কথা চালিয়ে যাওয়াই লক্ষ্য।"}]}]}]}'::jsonb, 'published', 'intermediate', 60, now())
  returning id into v_lesson;

  values (v_lesson, 'Practice: দৈনন্দিন Spoken English', 'Exercises from the book, checked automatically.', 'intermediate', 15, 10, true)
  returning id into v_qset;










end $$;
